import 'dart:async';
import 'dart:convert';
import 'package:final_destination/booking_history.dart';
import 'package:flutter/material.dart';
import 'package:final_destination/changepassword.dart';
import 'package:final_destination/login.dart';
import 'package:final_destination/sendfeedback.dart';
import 'package:final_destination/sendreview.dart';
import 'package:final_destination/view_travel_company.dart';
import 'package:final_destination/viewbooking_status.dart';
import 'package:final_destination/viewpackage.dart';
import 'package:final_destination/viewpayment.dart';
import 'package:final_destination/viewprofile.dart';
import 'package:final_destination/viewreview.dart';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';

void main() {
  runApp(UserHomeApp());
}

class UserHomeApp extends StatelessWidget {
  const UserHomeApp({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        primaryColor: const Color(0xFF0F2A1D),
        fontFamily: 'Poppins',
        scaffoldBackgroundColor: const Color(0xFFE3EED4),
      ),
      home: UserHomePage(),
    );
  }
}

class WishlistItem {
  final String id;
  final String title;
  final String price;
  final String image;
  final String companyName;

  WishlistItem({
    required this.id,
    required this.title,
    required this.price,
    required this.image,
    required this.companyName,
  });
}

class Booking {
  final String id;
  final String status;
  final String date;
  final String total_person;
  final String photo;
  final String amount;
  final String package_details;
  final String travelcompany_name;

  Booking({
    required this.id,
    required this.status,
    required this.date,
    required this.total_person,
    required this.photo,
    required this.amount,
    required this.package_details,
    required this.travelcompany_name,
  });
}

class UserHomePage extends StatefulWidget {
  const UserHomePage({Key? key}) : super(key: key);

  @override
  State<UserHomePage> createState() => _UserHomePageState();
}

class _UserHomePageState extends State<UserHomePage> {
  int _currentIndex = 0;
  int _selectedCategory = 0;
  int _wishlistCount = 0;
  final PageController _pageController = PageController();
  final PageController _slideshowController = PageController();
  List<Package> _allPackages = [];
  List<Package> _filteredPackages = [];
  List<Package> _featuredPackages = [];
  List<TravelCompany> _allTravelCompanies = [];
  List<WishlistItem> _wishlistItems = [];
  List<Booking> _userBookings = [];
  bool _isSearching = false;
  bool _isLoadingPackages = false;
  bool _isLoadingCompanies = false;
  bool _isLoadingBookings = false;
  TextEditingController _searchController = TextEditingController();

  // User profile data
  String _userName = "Guest";
  String _userEmail = "";
  String _userPhoto = "";
  String _userId = "";
  String _userPhone = "";
  bool _isLoadingProfile = false;

  // Slideshow variables
  int _currentSlide = 0;
  Timer? _slideshowTimer;

  // Navigation items
  final List<String> navItems = [];

  @override
  void initState() {
    super.initState();
    _fetchPackagesForSearch();
    _fetchTravelCompanies();
    _getUserData();
    _fetchUserBookings();
    _startSlideshow();
    _loadWishlist();
  }

  @override
  void dispose() {
    _pageController.dispose();
    _slideshowController.dispose();
    _slideshowTimer?.cancel();
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _fetchUserBookings() async {
    setState(() => _isLoadingBookings = true);
    try {
      SharedPreferences prefs = await SharedPreferences.getInstance();
      String uid = prefs.getString('uid') ?? "";
      String ipAddress = prefs.getString('ip') ?? "http://localhost";

      var response = await http.post(
        Uri.parse("$ipAddress/user_viewbooking_status"),
        body: {"uid": uid},
      );

      if (response.statusCode == 200) {
        var jsonData = json.decode(response.body);
        List<Booking> bookings = [];
        if (jsonData["message"] != null) {
          for (var booking in jsonData["message"]) {
            bookings.add(Booking(
              id: booking["id"].toString(),
              status: booking["status"] ?? "",
              date: booking["date"].toString(),
              total_person: booking["total_person"].toString(),
              photo: "$ipAddress${booking["photo"] ?? ""}",
              amount: booking["amount"].toString(),
              package_details: booking["package_details"].toString(),
              travelcompany_name: booking["travelcompany_name"].toString(),
            ));
          }
        }
        setState(() {
          _userBookings = bookings;
          _isLoadingBookings = false;
        });
      } else {
        setState(() => _isLoadingBookings = false);
      }
    } catch (e) {
      print('Error fetching bookings: $e');
      setState(() => _isLoadingBookings = false);
    }
  }

  Future<void> _getUserData() async {
    setState(() => _isLoadingProfile = true);
    SharedPreferences prefs = await SharedPreferences.getInstance();
    setState(() {
      _userId = prefs.getString('uid') ?? "";
      _userName = prefs.getString('username') ?? "Traveler";
      _userEmail = prefs.getString('email') ?? "user@example.com";
      _userPhoto = prefs.getString('user_photo') ?? "";
      _userPhone = prefs.getString('phone') ?? "";
      _isLoadingProfile = false;
    });
    _fetchUserProfileFromApi();
  }

  Future<void> _fetchUserProfileFromApi() async {
    try {
      SharedPreferences prefs = await SharedPreferences.getInstance();
      String uid = prefs.getString('uid') ?? "";
      String ipAddress = prefs.getString('ip') ?? "http://localhost";
      if (uid.isEmpty) return;
      var response = await http.post(
        Uri.parse("$ipAddress/user_viewprofile"),
        body: {"uid": uid},
      );
      if (response.statusCode == 200) {
        var jsonData = json.decode(response.body);
        if (jsonData["message"] != null && jsonData["message"].isNotEmpty) {
          var userData = jsonData["message"][0];
          setState(() {
            _userName = userData["name"] ?? _userName;
            _userEmail = userData["email"] ?? _userEmail;
            _userPhoto = userData["photo"] != null ? "$ipAddress${userData["photo"]}" : _userPhoto;
            _userPhone = userData["phone"] ?? _userPhone;
          });
          await prefs.setString('username', _userName);
          await prefs.setString('email', _userEmail);
          await prefs.setString('user_photo', _userPhoto);
          await prefs.setString('phone', _userPhone);
        }
      }
    } catch (e) {
      print('Error fetching profile from API: $e');
    }
  }

  Future<void> _loadWishlist() async {
    SharedPreferences prefs = await SharedPreferences.getInstance();
    String? wishlistData = prefs.getString('wishlist');
    if (wishlistData != null) {
      try {
        List<dynamic> decodedList = json.decode(wishlistData);
        setState(() {
          _wishlistItems = decodedList.map((item) => WishlistItem(
            id: item['id'],
            title: item['title'],
            price: item['price'],
            image: item['image'],
            companyName: item['companyName'],
          )).toList();
          _wishlistCount = _wishlistItems.length;
        });
      } catch (e) {
        print('Error loading wishlist: $e');
      }
    }
  }

  Future<void> _saveWishlist() async {
    SharedPreferences prefs = await SharedPreferences.getInstance();
    List<Map<String, dynamic>> wishlistData = _wishlistItems.map((item) => {
      'id': item.id,
      'title': item.title,
      'price': item.price,
      'image': item.image,
      'companyName': item.companyName,
    }).toList();
    await prefs.setString('wishlist', json.encode(wishlistData));
  }

  void _toggleWishlist(Package package) {
    setState(() {
      int existingIndex = _wishlistItems.indexWhere((item) => item.id == package.id);
      if (existingIndex >= 0) {
        _wishlistItems.removeAt(existingIndex);
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${package.title} removed from wishlist'),
            backgroundColor: Colors.red,
            duration: const Duration(seconds: 2),
          ),
        );
      } else {
        _wishlistItems.add(WishlistItem(
          id: package.id,
          title: package.title,
          price: package.amount,
          image: package.photo,
          companyName: package.name,
        ));
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${package.title} added to wishlist'),
            backgroundColor: const Color(0xFF0F2A1D),
            duration: const Duration(seconds: 2),
            action: SnackBarAction(
              label: 'VIEW',
              textColor: Colors.white,
              onPressed: () {
                setState(() {
                  _currentIndex = 2;
                  _pageController.jumpToPage(2);
                });
              },
            ),
          ),
        );
      }
      _wishlistCount = _wishlistItems.length;
      _saveWishlist();
    });
  }

  bool _isInWishlist(String id) => _wishlistItems.any((item) => item.id == id);

  void _removeFromWishlist(String id) {
    setState(() {
      _wishlistItems.removeWhere((item) => item.id == id);
      _wishlistCount = _wishlistItems.length;
      _saveWishlist();
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Item removed from wishlist'),
          backgroundColor: Colors.red,
          duration: const Duration(seconds: 2),
        ),
      );
    });
  }

  void _clearWishlist() {
    setState(() {
      _wishlistItems.clear();
      _wishlistCount = 0;
      _saveWishlist();
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Wishlist cleared'),
          backgroundColor: const Color(0xFF0F2A1D),
          duration: const Duration(seconds: 2),
        ),
      );
    });
  }

  // View package details (eye button)
  void _viewPackageDetails(String packageId) {
    final package = _allPackages.firstWhere(
          (p) => p.id == packageId,
      orElse: () => _allPackages.first,
    );
    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (context) => PackageDetailsPage(package: package),
      ),
    );
  }

  void _startSlideshow() {
    _slideshowTimer?.cancel();
    _slideshowTimer = Timer.periodic(const Duration(seconds: 3), (timer) {
      if (_slideshowController.hasClients && _featuredPackages.isNotEmpty) {
        int nextPage = _currentSlide + 1;
        if (nextPage >= _featuredPackages.length) nextPage = 0;
        _slideshowController.animateToPage(
          nextPage,
          duration: const Duration(milliseconds: 500),
          curve: Curves.easeInOut,
        );
      }
    });
  }

  Future<void> _fetchPackagesForSearch() async {
    try {
      setState(() => _isLoadingPackages = true);
      SharedPreferences prefs = await SharedPreferences.getInstance();
      String userId = prefs.getString("lid") ?? "";
      String ipAddress = prefs.getString("ip") ?? "http://localhost";

      var response = await http.post(
          Uri.parse("$ipAddress/userviewpackage"),
          body: {"id": userId}
      );

      if (response.statusCode == 200) {
        var jsonData = json.decode(response.body);
        List<Package> fetchedPackages = [];
        for (var packageData in jsonData["message"]) {
          Package package = Package(
            id: packageData["id"].toString(),
            title: packageData["title"] ?? "",
            description: packageData["description"] ?? "",
            name: packageData["name"] ?? "",
            packageDetails: packageData["package_details"] ?? "",
            amount: packageData["amount"] ?? "0",
            photo: "$ipAddress${packageData["photo1"] ?? ""}",
            photo2: packageData["photo2"] != null ? "$ipAddress${packageData["photo2"]}" : null,
            photo3: packageData["photo3"] != null ? "$ipAddress${packageData["photo3"]}" : null,
          );
          fetchedPackages.add(package);
        }
        setState(() {
          _allPackages = fetchedPackages;
          _filteredPackages = fetchedPackages;
          _featuredPackages = fetchedPackages.take(5).toList();
          _isLoadingPackages = false;
        });
      } else {
        setState(() => _isLoadingPackages = false);
      }
    } catch (e) {
      setState(() => _isLoadingPackages = false);
    }
  }

  Future<void> _fetchTravelCompanies() async {
    try {
      setState(() => _isLoadingCompanies = true);
      SharedPreferences prefs = await SharedPreferences.getInstance();
      String userId = prefs.getString("lid") ?? "";
      String ipAddress = prefs.getString("ip") ?? "http://localhost";

      var response = await http.post(
          Uri.parse("$ipAddress/user_view_travel_company"),
          body: {"id": userId}
      );

      if (response.statusCode == 200) {
        var jsonData = json.decode(response.body);
        List<TravelCompany> fetchedCompanies = [];
        for (var companyData in jsonData["message"]) {
          TravelCompany company = TravelCompany(
            id: companyData["id"].toString(),
            name: companyData["name"] ?? "",
            address: companyData["address"]?.toString() ?? "",
            phone: companyData["phone"]?.toString() ?? "",
            email: companyData["email"]?.toString() ?? "",
            photo: "$ipAddress${companyData["photo"] ?? ""}",
            place: companyData["place"]?.toString() ?? "",
            rating: companyData["rating"] != null ? double.parse(companyData["rating"].toString()) : 4.5,
            tours: companyData["tours"] != null ? int.parse(companyData["tours"].toString()) : 50,
          );
          fetchedCompanies.add(company);
        }
        setState(() {
          _allTravelCompanies = fetchedCompanies;
          _isLoadingCompanies = false;
        });
      } else {
        setState(() => _isLoadingCompanies = false);
      }
    } catch (e) {
      setState(() => _isLoadingCompanies = false);
    }
  }

  void _searchPackages(String query) {
    setState(() {
      _isSearching = query.isNotEmpty;
      if (query.isEmpty) {
        _filteredPackages = _allPackages;
      } else {
        _filteredPackages = _allPackages.where((package) {
          final titleLower = package.title.toLowerCase();
          final detailsLower = package.packageDetails.toLowerCase();
          final queryLower = query.toLowerCase();
          return titleLower.contains(queryLower) || detailsLower.contains(queryLower);
        }).toList();
      }
    });
  }

