  Widget _buildSearchResults() {
    if (_isLoadingPackages) {
      return Container(
        padding: const EdgeInsets.all(40),
        child: Column(
          children: [
            const CircularProgressIndicator(color: Color(0xFF0F2A1D)),
            const SizedBox(height: 20),
            Text('Loading packages...', style: TextStyle(color: const Color(0xFF0F2A1D))),
          ],
        ),
      );
    }

    if (_filteredPackages.isEmpty && _searchController.text.isNotEmpty) {
      return Container(
        padding: const EdgeInsets.all(40),
        child: Column(
          children: [
            const Icon(Icons.search_off, size: 60, color: Colors.grey),
            const SizedBox(height: 20),
            const Text('No packages found', style: TextStyle(fontSize: 18, color: Colors.grey, fontWeight: FontWeight.w500)),
            const SizedBox(height: 10),
            Text('No packages match "${_searchController.text}"', style: const TextStyle(color: Colors.grey)),
            const SizedBox(height: 20),
            ElevatedButton(
              onPressed: () {
                _searchController.clear();
                _searchPackages('');
              },
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFF0F2A1D),
                padding: const EdgeInsets.symmetric(horizontal: 30, vertical: 12),
              ),
              child: const Text('Clear Search'),
            ),
          ],
        ),
      );
    }

    return Padding(
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text('Search Results (${_filteredPackages.length})', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold, color: const Color(0xFF0F2A1D))),
              if (_searchController.text.isNotEmpty)
                TextButton(
                  onPressed: () {
                    _searchController.clear();
                    _searchPackages('');
                  },
                  child: const Text('Clear', style: TextStyle(color: Colors.red)),
                ),
            ],
          ),
          const SizedBox(height: 20),
          ListView.builder(
            shrinkWrap: true,
            physics: const NeverScrollableScrollPhysics(),
            itemCount: _filteredPackages.length,
            itemBuilder: (context, index) {
              return _buildSearchPackageCard(_filteredPackages[index]);
            },
          ),
        ],
      ),
    );
  }

  Widget _buildSearchPackageCard(Package package) {
    bool isFavorite = _isInWishlist(package.id);

    return Container(
      margin: const EdgeInsets.only(bottom: 20),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(15),
        boxShadow: [
          BoxShadow(
            color: Colors.grey.withOpacity(0.2),
            spreadRadius: 2,
            blurRadius: 10,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          ClipRRect(
            borderRadius: const BorderRadius.only(topLeft: Radius.circular(15), topRight: Radius.circular(15)),
            child: Image.network(
              package.photo,
              height: 180,
              width: double.infinity,
              fit: BoxFit.cover,
              loadingBuilder: (context, child, loadingProgress) {
                if (loadingProgress == null) return child;
                return Container(height: 180, color: Colors.grey[200], child: const Center(child: CircularProgressIndicator(color: Color(0xFF0F2A1D))));
              },
              errorBuilder: (context, error, stackTrace) => Container(
                height: 180,
                color: Colors.grey[200],
                child: const Center(child: Icon(Icons.image_not_supported, color: Colors.grey, size: 50)),
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(20),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Expanded(
                      child: Text(
                        package.title,
                        style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold, color: Color(0xFF0F2A1D)),
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                      decoration: BoxDecoration(color: const Color(0xFF0F2A1D).withOpacity(0.1), borderRadius: BorderRadius.circular(8)),
                      child: Text('₹${package.amount}', style: const TextStyle(fontWeight: FontWeight.bold, color: Color(0xFF0F2A1D))),
                    ),
                  ],
                ),
                const SizedBox(height: 10),
                Row(
                  children: [
                    const Icon(Icons.business, size: 16, color: Colors.grey),
                    const SizedBox(width: 5),
                    Expanded(
                      child: Text(
                        package.name,
                        style: const TextStyle(color: Colors.grey, fontSize: 14),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 15),
                Text(
                  package.description.length > 150 ? '${package.description.substring(0, 150)}...' : package.description,
                  style: const TextStyle(color: Colors.grey, fontSize: 14, height: 1.5),
                  maxLines: 3,
                  overflow: TextOverflow.ellipsis,
                ),
                const SizedBox(height: 20),
                Row(
                  children: [
                    Expanded(
                      child: ElevatedButton(
                        onPressed: () => _viewPackageDetails(package.id),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: const Color(0xFF0F2A1D),
                          padding: const EdgeInsets.symmetric(vertical: 12),
                          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),
                        ),
                        child: const Text('VIEW DETAILS', style: TextStyle(fontWeight: FontWeight.bold, color: Colors.white)),
                      ),
                    ),
                    const SizedBox(width: 10),
                    Container(
                      decoration: BoxDecoration(
                        border: Border.all(color: const Color(0xFF0F2A1D).withOpacity(0.3)),
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: IconButton(
                        icon: Icon(isFavorite ? Icons.favorite : Icons.favorite_border, color: isFavorite ? Colors.red : const Color(0xFF0F2A1D)),
                        onPressed: () => _toggleWishlist(package),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildToursSection() {
    final screenHeight = MediaQuery.of(context).size.height;
    return Container(
      padding: const EdgeInsets.symmetric(vertical: 40, horizontal: 20),
      color: const Color(0xFFE3EED4),
      child: Column(
        children: [
          Column(
            children: [
              Text('# FINAL DESTINATION', style: TextStyle(fontSize: 14, color: const Color(0xFF0F2A1D), fontWeight: FontWeight.bold, letterSpacing: 2)),
              const SizedBox(height: 10),
              Text('Popular Travel Packages', style: TextStyle(fontSize: 28, fontWeight: FontWeight.bold, color: const Color(0xFF0F2A1D))),
              const SizedBox(height: 20),
              Container(width: 80, height: 3, color: const Color(0xFF0F2A1D)),
              const SizedBox(height: 30),
            ],
          ),
          SizedBox(
            height: screenHeight * 0.45,
            child: _allPackages.isEmpty
                ? const Center(child: Text('No packages available', style: TextStyle(color: Colors.grey, fontSize: 16)))
                : ListView.builder(
              scrollDirection: Axis.horizontal,
              itemCount: _allPackages.length > 4 ? 4 : _allPackages.length,
              itemBuilder: (context, index) {
                final package = _allPackages[index];
                bool isFavorite = _isInWishlist(package.id);
                return Container(
                  width: 280,
                  margin: const EdgeInsets.only(right: 20),
                  child: _buildTourCard(package: package, isFavorite: isFavorite),
                );
              },
            ),
          ),
          const SizedBox(height: 30),
          ElevatedButton(
            onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (context) => const viewpackage())),
            style: ElevatedButton.styleFrom(
              backgroundColor: const Color(0xFF0F2A1D),
              padding: const EdgeInsets.symmetric(horizontal: 40, vertical: 12),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30)),
            ),
            child: const Text('VIEW ALL PACKAGES', style: TextStyle(fontSize: 14, fontWeight: FontWeight.bold, color: Colors.white, letterSpacing: 1)),
          ),
        ],
      ),
    );
  }

