            ),
            Padding(
              padding: const EdgeInsets.all(20),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Title and Price
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Expanded(
                        child: Text(
                          package.title,
                          style: const TextStyle(
                            fontSize: 24,
                            fontWeight: FontWeight.bold,
                            color: Color(0xFF0F2A1D),
                          ),
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                        decoration: BoxDecoration(
                          color: const Color(0xFF0F2A1D).withOpacity(0.1),
                          borderRadius: BorderRadius.circular(20),
                        ),
                        child: Text(
                          '₹${package.amount}',
                          style: const TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.bold,
                            color: Color(0xFF0F2A1D),
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  // Company Name
                  Row(
                    children: [
                      const Icon(Icons.business, size: 20, color: Colors.grey),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          package.name,
                          style: const TextStyle(fontSize: 16, color: Colors.grey),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 20),
                  // Description
                  const Text(
                    'Description',
                    style: TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.bold,
                      color: Color(0xFF0F2A1D),
                    ),
                  ),
                  const SizedBox(height: 10),
                  Text(
                    package.description,
                    style: const TextStyle(fontSize: 16, color: Colors.black87, height: 1.5),
                    softWrap: true,
                  ),
                  const SizedBox(height: 20),
                  // Package Details
                  const Text(
                    'Package Details',
                    style: TextStyle(
                      fontSize: 18,
                      fontWeight: FontWeight.bold,
                      color: Color(0xFF0F2A1D),
                    ),
                  ),
                  const SizedBox(height: 10),
                  Text(
                    package.packageDetails,
                    style: const TextStyle(fontSize: 16, color: Colors.black87, height: 1.5),
                    softWrap: true,
                  ),
                  const SizedBox(height: 30),
                  // BOOK NOW BUTTON REMOVED
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class Package {
  final String id;
  final String title;
  final String description;
  final String name;
  final String packageDetails;
  final String amount;
  final String photo;
  final String? photo2;
  final String? photo3;

  Package({
    required this.id,
    required this.title,
    required this.description,
    required this.name,
    required this.packageDetails,
    required this.amount,
    required this.photo,
    this.photo2,
    this.photo3,
  });
}

class TravelCompany {
  final String id;
  final String name;
  final String address;
  final String phone;
  final String email;
  final String photo;
  final String place;
  final double rating;
  final int tours;

  TravelCompany({
    required this.id,
    required this.name,
    required this.address,
    required this.phone,
    required this.email,
    required this.photo,
    required this.place,
    this.rating = 4.5,
    this.tours = 50,
  });
}